#include <WiFi.h>
#include <DNSServer.h>
#include <WebServer.h>
DNSServer dns;
WebServer web(80);

void setup() {
  WiFi.softAP("{{ap_name}}");
  dns.start(53, "*", WiFi.softAPIP());
  web.onNotFound([]() {
    web.send(200, "text/html", "<h1>Setup</h1><form><input name=ssid><input name=pw><button>save</button></form>");
  });
  web.begin();
}

void loop() { dns.processNextRequest(); web.handleClient(); }
